  var GL = { home:'\u2302', people:'\u25c9', daily:'\u25ce', calendar:'\u25e6', photos:'\u25e3', groups:'\u2b22', network:'\u2b61', audit:'\u2713', council:'\u265c', stats:'\u25a5', merge:'\u29c9', danger:'\u26a0', settings:'\u2699' };
