  if(x + w > NET.W - 4) x = ev.clientX - r.left - w - 10;
  if(y + h > NET.H - 4) y = ev.clientY - r.top - h - 10;
  el.style.transform = 'translate3d(' + Math.max(2, x).toFixed(1) + 'px,' + Math.max(2, y).toFixed(1) + 'px,0)';
