        if(p[0] < -80 || p[1] < -80 || p[0] > NET.W + 80 || p[1] > NET.H + 80) return;
        if(n.hub){ var hp = HP(n.hub); ctx.moveTo(hp[0], hp[1]); ctx.lineTo(p[0], p[1]); }
