/* Anchor the panel under the Quick Add button (V3.70.0, JD): the panel
   used to be pinned to the right edge of the screen while the button
   sits mid-topbar, so opening it threw the eye across the display.
   The page itself never moves — the panel is fixed-position and the
   app shell does not reflow (see the qa-on class fix in the CSS). */
function qaPlacePanel(){
  var p = $('.qa-panel'); if(!p) return;
  var b = $('.qadd');
  if(!b || window.innerWidth <= 560){ p.style.left = ''; p.style.right = ''; p.style.top = ''; return; }
  var r = b.getBoundingClientRect();
  var w = Math.min(448, window.innerWidth - 20);
  var left = Math.max(8, Math.min(r.left, window.innerWidth - w - 8));
  p.style.left = left + 'px'; p.style.right = 'auto'; p.style.top = (r.bottom + 8) + 'px';
}
function qaOpen(mode){
  qaEnsure();
  QA.prevFocus = (document.activeElement && document.activeElement !== document.body) ? document.activeElement : null;
  QA.open = true;
  $('#qawrap').hidden = false;
  document.body.classList.add('qa-on');
  qaPlacePanel();
  qaSetMode(mode || 'log');
}
function qaClose(){
  QA.open = false;
  var w = $('#qawrap'); if(w) w.hidden = true;
  document.body.classList.remove('qa-on');
  if(QA.watchT){ clearInterval(QA.watchT); QA.watchT = null; }
  var f = QA.prevFocus; QA.prevFocus = null;
  if(f && document.contains(f) && f.focus){ try{ f.focus(); }catch(x){} }
}
function qaSetMode(m){
  QA.mode = m;
  $$('#qawrap [data-qmode]').forEach(function(b){ b.classList.toggle('on', b.getAttribute('data-qmode') === m); });
  $$('#qawrap .qa-sec').forEach(function(s){ s.hidden = s.getAttribute('data-sec') !== m; });
  qaPaintQueueCount();
  if(m === 'log'){ qaApplyTog(); qaPaintLogList(); var q = $('#qa-q'); if(q && !QA.di) q.focus(); else { var s2 = $('#qa-sum'); if(s2) s2.focus(); } }
  if(m === 'prox'){ qaPaintProxList(); var pq = $('#qa-px-q'); if(pq && QA.pxDi == null) pq.focus(); else { var pl = $('#qa-px-place'); if(pl) pl.focus(); } }
  if(m === 'new'){ var f = $('#qa-np-first'); if(f) f.focus(); }
  if(m === 'queue'){ qaPaintQueueResults(); qaPaintQueue(); var qq = $('#qa-qq'); if(qq) qq.focus(); }
}
function qaStatus(msg, kind){
  var st = $('#qa-status'); if(!st) return;
  st.textContent = msg || '';
  st.className = 'qa-status' + (kind ? ' ' + kind : '');
}
/* after a save, follow the person's outbox item until the Sheet acks it */
function qaWatchWrite(id, baseMsg){
  if(QA.watchT) clearInterval(QA.watchT);
  var t0 = Date.now();
  QA.watchT = setInterval(function(){
    if(!QA.open){ clearInterval(QA.watchT); QA.watchT = null; return; }
    var logged = POOL.log.some(function(en){ return en.id === id && en.t > t0 - 2000; });
    if(logged){ qaStatus(baseMsg + ' Written to the Sheet.', 'ok'); clearInterval(QA.watchT); QA.watchT = null; return; }
    var it = null;
    for(var i = 0; i < OUT.items.length; i++) if(OUT.items[i].id === id){ it = OUT.items[i]; break; }
    if(it && it.stuck){ qaStatus(baseMsg + ' Stuck in the Save Pool: ' + it.stuck, 'err'); clearInterval(QA.watchT); QA.watchT = null; return; }
    if(Date.now() - t0 > 12000){ qaStatus(baseMsg + ' Still saving — it stays tracked in the Save Pool.', ''); clearInterval(QA.watchT); QA.watchT = null; }
  }, 600);
}
/* --- people picker (shared by Log and Queue-add) --- */
function qaSuggestions(){
  return people().slice().sort(function(a, b){
    var x = flexKey(gv(D.directory[a], 'last_contact')) || '', y = flexKey(gv(D.directory[b], 'last_contact')) || '';
    if(x !== y) return x < y ? 1 : -1;
    return (D.directory[b].strength || 0) - (D.directory[a].strength || 0);
  }).slice(0, 8);
}
/* V3.60.0 (JD): every person row in Quick Add carries a direct way
   to the profile — a small person-icon button at the row's right
   edge. The row itself keeps its select/log behavior (it is a div
   now so the button can nest legally); qaOnClick resolves the
   innermost control first, so the jump never falls through to pick. */
function qaOpenBtn(di){
  var nm = dispName(D.directory[di]);
  return '<button type="button" class="ib qa-open" data-qopen="' + di + '" aria-label="Open ' + esc(nm) + '’s profile" title="Open profile">' + ic('user', 15) + '</button>';
}
function qaRowHTML(di, i, hi){
  var e = D.directory[di];
  var hiv = (hi == null ? QA.hi : hi);
  var sub = [infoLine(e), lcLabel(e) ? 'Last ' + lcLabel(e) : '', effHandle(e) ? '@' + effHandle(e) : ''].filter(Boolean).join(' · ');
  return '<div class="qa-row' + (i === hiv ? ' on' : '') + '" data-qdi="' + di + '" role="button">' + avatar(e, 'sm') +
    '<span class="qa-rmain"><b>' + esc(dispName(e)) + '</b>' + milBadge(e) + '<small>' + esc(sub) + '</small></span>' + qaOpenBtn(di) + '</div>';
}
function qaPaintLogList(){
  var list = $('#qa-list'), lh = $('#qa-lh'); if(!list) return;
  var q = ($('#qa-q') ? $('#qa-q').value : '').trim();
  QA.rows = q ? searchPeople(q, 8) : qaSuggestions();
  QA.hi = Math.min(QA.hi, Math.max(0, QA.rows.length - 1));
  if(lh) lh.textContent = q ? (QA.rows.length ? 'Matches' : '') : 'Recently contacted';
  list.innerHTML = QA.rows.length ? QA.rows.map(function(di, i){ return qaRowHTML(di, i); }).join('') : '<div class="qa-none">No one matches.</div>';
  var pw = $('#qa-pickwrap'); if(pw) pw.hidden = QA.di != null;
  var pk = $('#qa-picked');
  if(pk){
    if(QA.di != null){
      var e = D.directory[QA.di];
      pk.innerHTML = avatar(e, 'sm') + '<span class="qa-rmain"><b>' + esc(dispName(e)) + '</b><small>' + esc(infoLine(e)) + '</small></span>' +
        qaOpenBtn(QA.di) +
        '<button type="button" class="btn ghost sm" data-qact="pickchange">Change</button>';
      pk.hidden = false;
    } else pk.hidden = true;
  }
  var dt = $('#qa-date'); if(dt) dt.textContent = 'Today · ' + qaDateLabel(todayStr());
}
/* --- Proximity tab (V3.70.0, JD): a first-class door of its own, peer
   to Log contact — its own picker state so the two tabs never entangle.
   Files a Proximity event (date + place only) via qaSaveProx; the Last
   Contact stamp is never in reach of this path. --- */
function qaPaintProxList(){
  var list = $('#qa-px-list'), lh = $('#qa-px-lh'); if(!list) return;
  var q = ($('#qa-px-q') ? $('#qa-px-q').value : '').trim();
  QA.pxRows = q ? searchPeople(q, 8) : qaSuggestions();
  QA.pxHi = Math.min(QA.pxHi, Math.max(0, QA.pxRows.length - 1));
  if(lh) lh.textContent = q ? (QA.pxRows.length ? 'Matches' : '') : 'Recently contacted';
  list.innerHTML = QA.pxRows.length ? QA.pxRows.map(function(di, i){ return qaRowHTML(di, i, QA.pxHi); }).join('') : '<div class="qa-none">No one matches.</div>';
  var pw = $('#qa-px-pickwrap'); if(pw) pw.hidden = QA.pxDi != null;
  var pk = $('#qa-px-picked');
  if(pk){
    if(QA.pxDi != null){
      var e = D.directory[QA.pxDi];
      pk.innerHTML = avatar(e, 'sm') + '<span class="qa-rmain"><b>' + esc(dispName(e)) + '</b><small>' + esc(infoLine(e)) + '</small></span>' +
        qaOpenBtn(QA.pxDi) +
        '<button type="button" class="btn ghost sm" data-qact="pxpickchange">Change</button>';
      pk.hidden = false;
    } else pk.hidden = true;
  }
  var dt = $('#qa-px-date'); if(dt && !dt.value) dt.value = todayStr();
}
function qaDoProx(){
  if(QA.pxDi == null){ qaStatus('Pick a person first.', 'err'); var q = $('#qa-px-q'); if(q) q.focus(); return; }
  var venue = $('#qa-px-place').value;
  if(!venue.trim()){ qaStatus('Name the place or context — that is the whole record.', 'err'); $('#qa-px-place').focus(); return; }
  var d = ($('#qa-px-date') ? $('#qa-px-date').value : '') || todayStr();
  if(!/^\d{4}-\d{2}-\d{2}$/.test(d)){ qaStatus('Pick a valid date.', 'err'); return; }
  var di = QA.pxDi, e = D.directory[di];
  if(!qaSaveProx(di, venue, d)){ qaStatus('That did not save. Try again.', 'err'); return; }
  var base = 'Logged proximity with ' + dispName(e) + ' — ' + venue.trim() + ' · ' + qaDateLabel(d) + '. Co-presence only: Last Contact untouched.';
  qaStatus(base + ' Saving through the Save Pool…', 'ok');
  qaWatchWrite(pkey(e), base);
  QA.pxDi = null; QA.pxHi = 0;
  $('#qa-px-place').value = ''; var pq = $('#qa-px-q'); if(pq) pq.value = '';
  qaPaintProxList(); qaPaintQueueCount();
  if(pq) pq.focus();
}
function qaPaintQueueResults(){
  var list = $('#qa-qlist'); if(!list) return;
  var q = ($('#qa-qq') ? $('#qa-qq').value : '').trim();
  if(!q){ list.innerHTML = ''; QA.rows = []; return; }
  var queued = {}; qaQueueEntries().forEach(function(en){ queued[en.di] = 1; });
  QA.rows = searchPeople(q, 8).filter(function(di){ return !queued[di]; });
  QA.hi = Math.min(QA.hi, Math.max(0, QA.rows.length - 1));
  list.innerHTML = QA.rows.length ? QA.rows.map(function(di, i){ return qaRowHTML(di, i); }).join('') : '<div class="qa-none">No one new matches.</div>';
}
function qaPick(di){
  if(QA.mode === 'prox'){
    QA.pxDi = di; qaPaintProxList();
    var pl = $('#qa-px-place'); if(pl) pl.focus();
    return;
  }
  if(QA.mode === 'queue'){
    var e0 = D.directory[di];
    if(qaQueueAdd(di)){ qaStatus('Added ' + dispName(e0) + ' to Up Next.', 'ok'); }
    else qaStatus(dispName(e0) + ' is already in Up Next.', '');
    var qq = $('#qa-qq'); if(qq){ qq.value = ''; qq.focus(); }
    qaPaintQueueResults(); qaPaintQueue(); qaPaintQueueCount();
    return;
  }
  QA.di = di; qaPaintLogList();
  var s = $('#qa-sum'); if(s) s.focus();
}
/* --- queue tab --- */
function qaPaintQueueCount(){
  var n = qaQueueEntries().length, el = $('#qa-qn');
  if(el) el.textContent = n ? ' · ' + n : '';
}
function qaPaintQueue(){
  var box = $('#qa-queue'); if(!box) return;
  var entries = qaQueueEntries();
  box.innerHTML = entries.length ? entries.map(function(en){
    var e = D.directory[en.di];
    var sub = [infoLine(e), lcLabel(e) ? 'Last ' + lcLabel(e) : ''].filter(Boolean).join(' · ');
    return '<div class="qa-qrow">' + avatar(e, 'sm') + '<span class="qa-rmain"><b>' + esc(dispName(e)) + '</b><small>' + esc(sub) + '</small></span>' +
      qaOpenBtn(en.di) +
      '<button type="button" class="btn ghost sm" data-qlog="' + en.di + '">Log</button>' +
      '<button type="button" class="ib qa-rm" data-qrm="' + en.di + '" aria-label="Remove from Up Next">' + ic('x', 14) + '</button></div>';
  }).join('') : '<div class="qa-none">Nobody up next. Add people above and they will wait here.</div>';
}
/* --- actions --- */
function qaDoLog(){
  if(QA.di == null){ qaStatus('Pick a person first.', 'err'); var q = $('#qa-q'); if(q) q.focus(); return; }
  if(QA.prox){
    var venue = $('#qa-sum').value;
    if(!venue.trim()){ qaStatus('Name the place or context — that is the whole record.', 'err'); $('#qa-sum').focus(); return; }
    var pdi = QA.di, pe = D.directory[pdi];
    if(!qaSaveProx(pdi, venue)){ qaStatus('That did not save. Try again.', 'err'); return; }
    var pbase = 'Logged proximity with ' + dispName(pe) + ' — ' + venue.trim() + ' · ' + qaDateLabel(todayStr()) + '. Co-presence only: Last Contact untouched.';
    qaStatus(pbase + ' Saving through the Save Pool…', 'ok');
    qaWatchWrite(pkey(pe), pbase);
    QA.di = null; QA.hi = 0;
    $('#qa-sum').value = ''; var pq = $('#qa-q'); if(pq){ pq.value = ''; }
    qaPaintLogList(); qaPaintQueueCount();
    if(pq) pq.focus();
    return;
  }
  var sum = $('#qa-sum').value, det = $('#qa-det').value;
  if(!sum.trim()){ qaStatus('Write what happened, one line — that line is the record.', 'err'); $('#qa-sum').focus(); return; }
  var di = QA.di, e = D.directory[di], on = QA.online;
  if(!qaSaveLog(di, sum, det, on)){ qaStatus('That did not save. Try again.', 'err'); return; }
  var base = 'Logged ' + (on ? 'online' : 'location') + ' contact with ' + dispName(e) + ' — ' + qaDateLabel(todayStr()) + '.';
  qaStatus(base + ' Saving through the Save Pool…', 'ok');
  qaWatchWrite(pkey(e), base);
  QA.di = null; QA.hi = 0;
  $('#qa-sum').value = ''; $('#qa-det').value = ''; var q2 = $('#qa-q'); if(q2){ q2.value = ''; }
  qaPaintLogList(); qaPaintQueueCount();
  if(q2) q2.focus();
}
function qaNpMatches(full){
  var lf = full.toLowerCase();
  return people().filter(function(di){ return dispName(D.directory[di]).toLowerCase() === lf; });
}
function qaDoCreate(force){
  var fn = $('#qa-np-first').value.trim(), ln = $('#qa-np-last').value.trim();
  var full = (fn + ' ' + ln).trim();
  if(!full){ qaStatus('Enter a name first.', 'err'); $('#qa-np-first').focus(); return; }
  var city = $('#qa-np-city').value.trim(), rel = $('#qa-np-rel').value.trim(), since = $('#qa-np-since').value.trim();
  if(since && !/^\d{4}$/.test(since)){ qaStatus('Known since needs a 4-digit year.', 'err'); $('#qa-np-since').focus(); return; }
  var warn = $('#qa-np-warn');
  if(!force){
    var hits = qaNpMatches(full);
    if(hits.length){
      QA.npWarn = true;
      warn.innerHTML = '<b>' + esc(full) + '</b> is already in the directory:' + hits.map(function(di){
        var e = D.directory[di];
        return '<span class="qa-warnrow">' + esc([infoLine(e), lcLabel(e) ? 'Last ' + lcLabel(e) : ''].filter(Boolean).join(' · ')) +
          '</span><button type="button" class="btn ghost sm" data-quse="' + di + '">Log contact with them instead</button>' +
          '<button type="button" class="btn ghost sm" data-qopen="' + di + '">Open profile</button>';
      }).join('') + '<button type="button" class="btn ghost sm" data-qact="npforce">Create anyway</button>';
      warn.hidden = false;
      qaStatus('Someone with that name is already on file.', 'err');
      return;
    }
  }
  warn.hidden = true; QA.npWarn = null;
  var slug = full.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), key = 'sf:' + slug, n = 2;
  while(PK2I[key] != null){ key = 'sf:' + slug + '-' + n; n++; }
  var e = { name:key, display:full, src:'subject', profile:{}, events:[], files:[], neighbors:[] };
  D.directory.push(e);
  var di = D.directory.length - 1;
  PK2I[key] = di;
  var dn = full.toLowerCase(); if(!(dn in BYN)) BYN[dn] = di;
  normEntry(e);
  var patch = { first_name:fn, last_name:ln, display_name:full, display:full, tier:'open' };
  if(city) patch.city = city;
  if(rel) patch.relationship = rel;
  if(since) patch.known_since = since;
  txn('Add person', function(){ queuePatch(di, patch); });
  var base = 'Added ' + full + ' — the row is created in the Sheet through the Save Pool.';
  qaStatus(base + ' Saving…', 'ok');
  qaWatchWrite(key, base);
  ['qa-np-first', 'qa-np-last', 'qa-np-city', 'qa-np-rel', 'qa-np-since'].forEach(function(id){ var el = document.getElementById(id); if(el) el.value = ''; });
  var done = $('#qa-np-done');
  if(done){
    done.innerHTML = '<span>' + esc(full) + ' is in. Log the first contact now:</span>' +
      '<button type="button" class="btn primary sm" data-qfirst="' + di + '">Log first contact</button>' + qaOpenBtn(di);
    done.hidden = false;
  }
  qaPaintQueueCount();
}
function qaOnClick(ev){
  var t = ev.target && ev.target.closest ? ev.target.closest('[data-qmode],[data-qact],[data-qdi],[data-qlog],[data-qrm],[data-quse],[data-qfirst],[data-qopen],[data-on],[data-prox]') : null;
  if(!t) return;
  if(t.hasAttribute('data-qmode')){ qaSetMode(t.getAttribute('data-qmode')); return; }
  if(t.hasAttribute('data-prox')){
    QA.prox = true;
    qaApplyTog();
    var ps = $('#qa-sum'); if(ps) ps.focus();
    return;
  }
  if(t.hasAttribute('data-on')){
    QA.online = t.getAttribute('data-on') === '1';
    QA.prox = false;
    qaApplyTog();
    return;
  }
  if(t.hasAttribute('data-qopen')){ var odi = +t.getAttribute('data-qopen'); qaClose(); openPerson(odi, null); return; }
  if(t.hasAttribute('data-qdi')){ qaPick(+t.getAttribute('data-qdi')); return; }
  if(t.hasAttribute('data-qlog')){ QA.di = +t.getAttribute('data-qlog'); qaSetMode('log'); qaPaintLogList(); var s = $('#qa-sum'); if(s) s.focus(); return; }
  if(t.hasAttribute('data-qrm')){
    var di = +t.getAttribute('data-qrm'), nm = dispName(D.directory[di]);
    qaQueueRemove(di); qaPaintQueue(); qaPaintQueueCount();
    qaStatus('Removed ' + nm + ' from Up Next.', '');
    return;
  }
  if(t.hasAttribute('data-quse')){ QA.di = +t.getAttribute('data-quse'); qaSetMode('log'); qaPaintLogList(); var s2 = $('#qa-sum'); if(s2) s2.focus(); return; }
  if(t.hasAttribute('data-qfirst')){ QA.di = +t.getAttribute('data-qfirst'); qaSetMode('log'); qaPaintLogList(); var s3 = $('#qa-sum'); if(s3) s3.focus(); return; }
  var act = t.getAttribute('data-qact');
  if(act === 'close') qaClose();
  else if(act === 'pickchange'){ QA.di = null; qaPaintLogList(); var q = $('#qa-q'); if(q) q.focus(); }
  else if(act === 'pxpickchange'){ QA.pxDi = null; qaPaintProxList(); var pq = $('#qa-px-q'); if(pq) pq.focus(); }
  else if(act === 'pxsave') qaDoProx();
  else if(act === 'logsave') qaDoLog();
  else if(act === 'npcreate') qaDoCreate(false);
  else if(act === 'npforce') qaDoCreate(true);
}
function qaOnInput(ev){
  if(ev.target.id === 'qa-q'){ QA.hi = 0; if(QA.di == null) qaPaintLogList(); }
  else if(ev.target.id === 'qa-px-q'){ QA.pxHi = 0; if(QA.pxDi == null) qaPaintProxList(); }
  else if(ev.target.id === 'qa-qq'){ QA.hi = 0; qaPaintQueueResults(); }
}
function qaOnKey(ev){
  var id = ev.target && ev.target.id;
  if(id === 'qa-px-q' && QA.pxDi == null){
    var prows = QA.pxRows || [];
    if(ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
      if(!prows.length) return;
      ev.preventDefault();
      QA.pxHi = ev.key === 'ArrowDown' ? Math.min(prows.length - 1, QA.pxHi + 1) : Math.max(0, QA.pxHi - 1);
      $$('#qa-px-list .qa-row').forEach(function(r, j){ r.classList.toggle('on', j === QA.pxHi); });
    }
    else if(ev.key === 'Enter'){
      if(prows.length && prows[QA.pxHi] != null){ ev.preventDefault(); qaPick(prows[QA.pxHi]); }
    }
    return;
  }
  if(ev.key === 'Enter' && id === 'qa-px-place'){ ev.preventDefault(); qaDoProx(); return; }
  if((id === 'qa-q' && QA.di == null) || id === 'qa-qq'){
    var rows = QA.rows || [];
    if(ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
      if(!rows.length) return;
      ev.preventDefault();
      QA.hi = ev.key === 'ArrowDown' ? Math.min(rows.length - 1, QA.hi + 1) : Math.max(0, QA.hi - 1);
      $$('#qawrap .qa-row').forEach(function(r, j){ r.classList.toggle('on', j === QA.hi); });
    }
    else if(ev.key === 'Enter'){
      if(rows.length && rows[QA.hi] != null){ ev.preventDefault(); qaPick(rows[QA.hi]); }
    }
    return;
  }
  if(ev.key === 'Enter' && (id === 'qa-sum' || id === 'qa-det')){ ev.preventDefault(); qaDoLog(); return; }
  if(ev.key === 'Enter' && /^qa-np-/.test(id || '')){ ev.preventDefault(); qaDoCreate(false); }
}

/* ============================================================
   Presentation hooks. CALM PASS 2026-10-13: numbers and bars
   render at their final values, the progress ring is set in
   place instantly, and the loading skeleton is static. Nothing
   here writes data, touches the outbox, or changes any payload.
   ============================================================ */
function pvReducedMotion(){ return !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches); }
function skeletonHTML(note){
  /* SWISS MONO 2026-10-15: route-aware skeletons — the silhouette mirrors
     the surface the URL is about to show (Audit card grid, profile
     columns, map block, People rows). Static under reduced motion (CSS). */
  var h = (location.hash || '').toLowerCase(), body = '', i;
  if(h.indexOf('audit') >= 0){
    var cards = '';
    for(i = 0; i < 6; i++) cards += '<div class="skl sk-acard"></div>';
    body = '<div class="sk-grid">' + cards + '</div>';
  } else if(h.indexOf('/p/') >= 0){
    body = '<div class="skl sk-hero"></div><div class="sk-cols"><div class="skl"></div><div class="skl"></div><div class="skl"></div></div>';
  } else if(h.indexOf('network') >= 0 || h.indexOf('family') >= 0){
    body = '<div class="skl sk-big"></div>';
  } else if(h === '' || h === '#/' || h.indexOf('home') >= 0){
    body = '<div class="skl sk-big"></div><div class="sk-cols"><div class="skl"></div><div class="skl"></div><div class="skl"></div></div>';
  } else {
    var rows = '';
    for(i = 0; i < 6; i++) rows += '<div class="skl-row"><span class="skl av"></span><span class="skl tx" style="width:' + (58 - (i % 3) * 8) + '%"></span><span class="skl tx s" style="width:22%"></span></div>';
    body = rows + '<div class="skl card"></div>';
  }
  return '<div class="page skel" aria-busy="true"><div class="skl head"></div>' + body +
    (note ? '<p class="dim center">' + esc(note) + '</p>' : '') + '</div>';
}



/* ============================================================
   PHASE 4 (V3.66.0) — WS-G compact contact-date editor, WS-D
   Manage area, WS-F Sandbox Stats Explorer.
   ============================================================ */

/* ---------- WS-G: compact contact-date editor ----------
   One editor for every contact stamp (Last Contact, Last Online,
   First Contact). Two ways in: stepwise list picking (year ->
   month -> day, stoppable at any level) and typed text (2024,
   2024-06, 2024-06-15, 2024/6/15, 20240615, Jun 2024,
   June 15 2024). Granularity is preserved exactly as entered.

   COMMIT RULE (the bug fix): text commits ONLY on Enter or the
   explicit Save button — never on input, never on blur, never on
   a timer. Clicking away leaves the editor open and the stored
   value untouched; Cancel or Escape discards the draft whole.

   Root cause of the old premature submit — two paths filed date
   text without Enter:
   (1) The Audit card's lastc editor was missing from
       audWireCard's enter-only exclusion lists (years/orgs/skills
       were on them, lastc was not), so a 900ms typing pause or a
       250ms blur committed the value. Fixed in audWireCard +
       audEnterKey (lastc now shares the years path).
   (2) Profile data-pk text inputs commit through the global
       change handler, and the DOM change event fires on blur —
       so the relationship editor's last_contact input filed on
       click-away. Fixed for dates by this component replacing
       that input; the change-handler validation stays as a
       backstop for any other data-pk date.
   Saves ride queuePatch inside txn (undoable, Save Pool). */
var CDE = null; /* {di, field, ctx, y, m, d, online, root} */
var CDE_MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var CDE_MON_FULL = { january:1, february:2, march:3, april:4, may:5, june:6, july:7, august:8, september:9, october:10, november:11, december:12, jan:1, feb:2, mar:3, apr:4, jun:6, jul:7, aug:8, sep:9, sept:9, oct:10, nov:11, dec:12 };
function cdePad(n){ return (n < 10 ? '0' : '') + n; }
function cdeParts(v){
  var m = /^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?$/.exec(String(v || '').trim());
  if(!m) return { y:0, m:0, d:0 };
  return { y:+m[1], m:m[2] ? +m[2] : 0, d:m[3] ? +m[3] : 0 };
}
function cdeVal(p){
  if(!p.y) return '';
  var s = String(p.y);
  if(p.m) s += '-' + cdePad(p.m);
  if(p.m && p.d) s += '-' + cdePad(p.d);
  return s;
}
function cdeDim(y, m){ return [31, ((y % 4 === 0 && y % 100 !== 0) || y % 400 === 0) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][(m || 1) - 1]; }
function cdeParseTyped(raw){
  var s = String(raw || '').trim();
  if(!s) return '';
  var mm;
  if((mm = /^([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})$/.exec(s)) && CDE_MON_FULL[mm[1].toLowerCase()])
    return ykDateVal(mm[3] + '-' + cdePad(CDE_MON_FULL[mm[1].toLowerCase()]) + '-' + cdePad(+mm[2]));
  if((mm = /^([A-Za-z]+)\.?\s+(\d{4})$/.exec(s)) && CDE_MON_FULL[mm[1].toLowerCase()])
    return ykDateVal(mm[2] + '-' + cdePad(CDE_MON_FULL[mm[1].toLowerCase()]));
  if((mm = /^(\d{1,2})\s+([A-Za-z]+)\.?\s+(\d{4})$/.exec(s)) && CDE_MON_FULL[mm[2].toLowerCase()])
    return ykDateVal(mm[3] + '-' + cdePad(CDE_MON_FULL[mm[2].toLowerCase()]) + '-' + cdePad(+mm[1]));
  s = s.replace(/[\/.]/g, '-').replace(/\s+/g, '');
  if(/^\d{8}$/.test(s)) return ykDateVal(s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6, 8));
  if(/^\d{6}$/.test(s)) return ykDateVal(s.slice(0, 4) + '-' + s.slice(4, 6));
  if(/^\d{4}$/.test(s)) return ykDateVal(s);
  var p = s.split('-');
  if(p.length === 3 && p[2].length === 4 && p[0].length <= 2) return ykDateVal(p[2] + '-' + cdePad(+p[0]) + '-' + cdePad(+p[1])); /* M-D-YYYY */
  if(p.length === 3) return ykDateVal(p[0] + '-' + cdePad(+p[1]) + '-' + cdePad(+p[2]));
  if(p.length === 2 && p[0].length === 4) return ykDateVal(p[0] + '-' + cdePad(+p[1]));
  if(p.length === 2 && p[1].length === 4) return ykDateVal(p[1] + '-' + cdePad(+p[0]));
  return null;
}
function cdeFieldLabel(field, ctx){
  if(ctx === 'mgonline') return 'Last Online';
  return { last_contact:'Last Contact', first_contact:'First Contact' }[field] || field;
}
function cdeCurVal(di, field){
  var e = D.directory[di]; if(!e) return '';
  return String(gv(e, field) || '').trim();
}
function cdeWidget(di, field, ctx){
  ctx = ctx || '';
  var e = D.directory[di]; if(!e) return '';
  var v = cdeCurVal(di, field), lab, has = !!v;
  if(ctx === 'mgonline'){ has = lcOnline(e) && !!v; lab = has ? lcDateLabel(v) : 'Not online'; }
  else if(field === 'first_contact' && !v){ var fc = firstContactOf(e); lab = fc ? lcDateLabel(fc) + ' · from events' : 'Not set'; }
  else lab = v ? lcDateLabel(v) : 'Not set';
  return '<span class="cde" data-cde="' + field + '">' +
    '<span class="cde-val' + (has ? '' : ' dim') + '">' + esc(lab) + '</span>' +
    '<button type="button" class="btn ghost sm" data-act="cdeedit" data-di="' + di + '" data-field="' + field + '" data-ctx="' + ctx + '">' + ic('edit', 12) + (has ? 'Edit' : 'Set') + '</button></span>';
}
function cdeCloseHost(o){
  if(!o || !o.root || !o.root.isConnected) return;
  var tmp = document.createElement('div');
  tmp.innerHTML = cdeWidget(o.di, o.field, o.ctx);
  if(tmp.firstChild) o.root.replaceWith(tmp.firstChild);
}
function cdeOpen(btn){
  var di = +btn.getAttribute('data-di'), field = btn.getAttribute('data-field'), ctx = btn.getAttribute('data-ctx') || '';
  var host = btn.closest('.cde'); if(!host || !D.directory[di]) return;
  if(CDE && CDE.root !== host) cdeCloseHost(CDE);
  var p = cdeParts(cdeCurVal(di, field));
  CDE = { di:di, field:field, ctx:ctx, y:p.y, m:p.m, d:p.d,
          online: ctx === 'mgonline' ? true : (field === 'last_contact' ? lcOnline(D.directory[di]) : false),
          root:host };
  cdePaint();
  var inp = $('.cde-in', host); if(inp){ inp.focus(); inp.select(); }
}
function cdePaint(){
  if(!CDE) return;
  var host = CDE.root; if(!host || !host.isConnected){ CDE = null; return; }
  var nowY = new Date().getFullYear(), y;
  var yBtns = '';
  for(y = Math.max(nowY, CDE.y || 0); y >= 1920; y--) yBtns += '<button type="button" class="cde-opt' + (CDE.y === y ? ' on' : '') + '" data-act="cdeopt" data-part="y" data-v="' + y + '">' + y + '</button>';
  var mBtns = '<button type="button" class="cde-opt wide' + (!CDE.m ? ' on' : '') + '" data-act="cdeopt" data-part="m" data-v="0">Year only</button>', m;
  for(m = 1; m <= 12; m++) mBtns += '<button type="button" class="cde-opt' + (CDE.m === m ? ' on' : '') + '" data-act="cdeopt" data-part="m" data-v="' + m + '">' + CDE_MON[m - 1] + '</button>';
  var dim = CDE.m ? cdeDim(CDE.y || nowY, CDE.m) : 31, d;
  var dBtns = '<button type="button" class="cde-opt wide' + (!CDE.d ? ' on' : '') + '" data-act="cdeopt" data-part="d" data-v="0">No day</button>';
  for(d = 1; d <= dim; d++) dBtns += '<button type="button" class="cde-opt' + (CDE.d === d ? ' on' : '') + '" data-act="cdeopt" data-part="d" data-v="' + d + '">' + d + '</button>';
  var val = cdeVal(CDE);
  host.innerHTML =
    '<span class="cde-pop" role="group" aria-label="' + esc(cdeFieldLabel(CDE.field, CDE.ctx)) + ' editor">' +
    '<span class="cde-cols">' +
      '<span class="cde-col"><span class="cde-cl">Year</span>' + yBtns + '</span>' +
      '<span class="cde-col"><span class="cde-cl">Month</span>' + mBtns + '</span>' +
      '<span class="cde-col"><span class="cde-cl">Day</span>' + dBtns + '</span>' +
    '</span>' +
    '<span class="cde-typerow"><input class="cde-in inp" value="' + esc(val) + '" placeholder="2024 · 2024-06 · 2024-06-15" autocomplete="off" spellcheck="false" aria-label="Type a date">' +
    '<span class="cde-hint">' + (val ? esc(ykLabelOf(val)) : 'Stop at any level — year, year + month, or a full date.') + '</span></span>' +
    (CDE.field === 'last_contact' && CDE.ctx !== 'mgonline' ? '<label class="cde-onl"><input type="checkbox" data-cdeonl' + (CDE.online ? ' checked' : '') + '> Online contact (not in person)</label>' : '') +
    '<span class="cde-acts"><button type="button" class="btn ghost sm" data-act="cdeclear">Clear</button><span class="sp"></span>' +
    '<button type="button" class="btn ghost sm" data-act="cdecancel">Cancel</button>' +
    '<button type="button" class="btn sm" data-act="cdesave">Save</button></span>' +
    '<span class="cde-note">Saves only on Save or Enter — typing and clicking away never file anything.</span></span>';
}
function cdeOpt(part, v){
  if(!CDE) return;
  v = +v;
  if(part !== 'y' && !CDE.y) CDE.y = new Date().getFullYear();
  if(part === 'y'){ CDE.y = v; if(!v){ CDE.m = 0; CDE.d = 0; } }
  if(part === 'm'){ CDE.m = v; if(!v) CDE.d = 0; }
  if(part === 'd'){ CDE.d = v; }
  if(CDE.d && CDE.m){ var dim = cdeDim(CDE.y || new Date().getFullYear(), CDE.m); if(CDE.d > dim) CDE.d = dim; }
  cdePaint();
  var b = $('[data-part="' + part + '"][data-v="' + v + '"]', CDE.root); if(b) b.focus();
}
function cdeSaveFrom(inp){
  if(!CDE) return;
  var v = cdeParseTyped(inp.value);
  if(v === null){ inp.classList.add('bad'); inp.focus(); return; }
  var p = cdeParts(v); CDE.y = p.y; CDE.m = p.m; CDE.d = p.d;
  cdeSave(true);
}
function cdeSave(fromTyped){
  if(!CDE) return;
  var inp = $('.cde-in', CDE.root);
  if(!fromTyped && inp && inp.value.trim() !== cdeVal(CDE)){
    var v = cdeParseTyped(inp.value);
    if(v === null){ inp.classList.add('bad'); inp.focus(); return; }
    var p = cdeParts(v); CDE.y = p.y; CDE.m = p.m; CDE.d = p.d;
  }
  var di = CDE.di, field = CDE.field, ctx = CDE.ctx, val = cdeVal(CDE);
  var patch = {}; patch[field] = val;
  if(field === 'last_contact') patch.last_contact_online = (ctx === 'mgonline') ? (val ? 'yes' : '') : (CDE.online ? 'yes' : '');
  CDE = null;
  txn(field === 'first_contact' ? 'Set first contact' : 'Set last contact', function(){ queuePatch(di, patch); });
  toast(cdeFieldLabel(field, ctx) + (val ? ' set to ' + ykLabelOf(val) : ' cleared') + ' — ' + dispName(D.directory[di]) + '.');
  if(ctx === 'profile'){ repaintSec('relationship'); repaintTop(); }
  else if(ctx === 'manage' || ctx === 'mgonline'){ mgPaintList(); }
  else render();
}
function cdeCancel(){ if(!CDE) return; var o = CDE; CDE = null; cdeCloseHost(o); }
function cdeClear(){ if(!CDE) return; CDE.y = 0; CDE.m = 0; CDE.d = 0; cdeSave(true); }
/* Keyboard support inside the open editor: arrows walk a column,
   Escape cancels. Runs in capture so it composes with the app's
   own key handlers; Enter on the typed input is handled by onKey. */
document.addEventListener('keydown', function(ev){
  if(!CDE || !CDE.root || !CDE.root.isConnected) return;
  var t = ev.target;
  if(!t.closest || !t.closest('.cde')) return;
  if(ev.key === 'Escape'){ ev.preventDefault(); cdeCancel(); return; }
  if((ev.key === 'ArrowDown' || ev.key === 'ArrowUp') && t.classList && t.classList.contains('cde-opt')){
    ev.preventDefault();
    var col = t.closest('.cde-col'); if(!col) return;
    var opts = $$('.cde-opt', col), i = opts.indexOf(t);
    var n = ev.key === 'ArrowDown' ? Math.min(opts.length - 1, i + 1) : Math.max(0, i - 1);
    if(opts[n]) opts[n].focus();
  }
}, true);

/* ---------- WS-D: upkeep tools (formerly the Manage area) ----------
   V4 Phase 3: the Manage container is dissolved. Its three tools
   keep their code and behaviour, re-homed: the contact stamps
   table and the Proximity bulk logger render on the Calendar
   (viewCalendar), and the Levels map renders in Settings
   (viewSettings). #/manage routes redirect in render(). */
var MGMT = { sort:'lastc', dir:1, q:'', shown:50 };
function mgStampVal(e, k){
  if(k === 'firstc') return firstContactOf(e);
  if(k === 'online') return lcOnline(e) ? String(gv(e, 'last_contact') || '') : '';
  return String(gv(e, 'last_contact') || '');
}
function mgRows(){
  var q = MGMT.q.trim().toLowerCase();
  var dis = people().filter(function(di){ var e = D.directory[di]; return e && (!q || dispName(e).toLowerCase().indexOf(q) >= 0); });
  var k = MGMT.sort, d = MGMT.dir;
  dis.sort(function(a, b){
    var ka = flexKey(mgStampVal(D.directory[a], k)), kb = flexKey(mgStampVal(D.directory[b], k));
    if(ka == null && kb == null) return dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
    if(ka == null) return d > 0 ? -1 : 1;   /* blanks are the lowest value (Danger Zone rule): ascending = blanks first */
    if(kb == null) return d > 0 ? 1 : -1;
    if(ka !== kb) return (ka - kb) * d;
    return dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
  });
  return dis;
}
function mgStampsHTML(){
  return '<div class="mg-tools">' +
    '<input id="mg-q" class="inp" placeholder="Search people" value="' + esc(MGMT.q) + '" autocomplete="off">' +
    '<label class="mg-sortlab">Sort by <select id="mg-sort" class="inp">' +
      [['lastc', 'Last Contact'], ['online', 'Last Online'], ['firstc', 'First Contact']].map(function(o){ return '<option value="' + o[0] + '"' + (MGMT.sort === o[0] ? ' selected' : '') + '>' + o[1] + '</option>'; }).join('') +
    '</select></label>' +
    '<button type="button" class="btn ghost sm" data-act="mgdir">' + (MGMT.dir > 0 ? 'Blank / oldest first' : 'Newest first') + '</button>' +
    '<span class="mg-count" id="mg-count"></span></div>' +
    '<div class="mg-head"><span>Person</span><span>Last Contact</span><span>Last Online</span><span>First Contact</span></div>' +
    '<div id="mglist"></div>';
}
function mgPaintList(){
  var box = $('#mglist'); if(!box) return;
  var dis = mgRows();
  var cnt = $('#mg-count'); if(cnt) cnt.textContent = dis.length + ' people';
  /* Editorial Grid (V3.73.0): the ledger renders in chapters of 50
     with a "show next 50" rule line — never 400+ rows in open flow. */
  var CAPN = Math.max(50, MGMT.shown || 50);
  box.innerHTML = dis.slice(0, CAPN).map(function(di){
    var e = D.directory[di];
    return '<div class="mg-row"><a class="mg-name" href="#/p/' + personId(e) + '" data-act="openp" data-di="' + di + '">' + avatar(e, 'sm') + '<span><b>' + esc(dispName(e)) + '</b><small>' + esc(gv(e, 'relationship') || '') + '</small></span></a>' +
      '<span class="mg-cell">' + cdeWidget(di, 'last_contact', 'manage') + '</span>' +
      '<span class="mg-cell">' + cdeWidget(di, 'last_contact', 'mgonline') + '</span>' +
      '<span class="mg-cell">' + cdeWidget(di, 'first_contact', 'manage') + '</span></div>';
  }).join('') + (dis.length > CAPN ? '<button type="button" class="mg-more" data-act="mgmore">Show next 50 &mdash; showing ' + CAPN + ' of ' + dis.length + '</button>' : '');
}
/* Levels manager. Assignments persist the way the app already
   persists local settings: a localStorage overlay (ncc_levels_v1),
   the same pattern as the org registry overlay. Since V3.68.0 the
   level also gates display through the top-bar role: a section is
   hidden entirely when the current role does not clear its level. */
var LVL_KEY = 'ncc_levels_v1';
function lvlRowsDef(){
  /* V4.3.0 (JD 2026-11-04): the Show tabs read as broken because
     nearly every section defaulted to Open — switching changed
     almost nothing. Defaults now carry the standing intent: Family
     and the Contact Log note are Personal, Traits are Private,
     the rest Open. JD can still reassign any of them here. */
  var rows = SECS.map(function(s){
    var def = s.id === 'persona' ? 'private' : (s.id === 'lima' ? 'personal' : 'open');
    var note = s.id === 'persona' ? 'Traits segment bars — Private by default' : (s.id === 'lima' ? 'Contact Log note — Personal by default' : '');
    return { id:'sec:' + s.id, name:s.t, kind: s.mv === 'c' ? 'connection' : 'about', def:def, note:note };
  });
  rows.push({ id:'family', name:'Family links', kind:'about', def:'personal', note:'Standing rule: Family = Personal.' });
  rows.push({ id:'stamps', name:'Contact stamps — Last Contact, Last Online, First Contact', kind:'connection', def:'open', note:'Edited in the Calendar stamps table and on profiles.' });
  return rows;
}
function lvlOverlay(){ try{ return JSON.parse(store(LVL_KEY) || '{}') || {}; }catch(x){ return {}; } }
function lvlOf(id){
  var o = lvlOverlay(); if(o[id]) return o[id];
  var rows = lvlRowsDef();
  for(var i = 0; i < rows.length; i++) if(rows[i].id === id) return rows[i].def;
  return 'open';
}
function secLevel(secId){ return lvlOf('sec:' + secId); }
function lvlSet(id, val){
  var o = lvlOverlay(); o[id] = val; store(LVL_KEY, JSON.stringify(o));
  toast('Level updated — sections above the current role are hidden app-wide.');
  render();
}
function mgLevelsHTML(){
  var rows = lvlRowsDef().map(function(r){
    var cur = lvlOf(r.id);
    return '<div class="mg-lvrow"><span class="mg-lvname"><b>' + esc(r.name) + '</b>' + (r.note ? '<small>' + esc(r.note) + '</small>' : '') + '</span>' +
      '<span>' + kindChip(r.kind, true) + '</span>' +
      '<span>' + (cur === 'open' ? '<span class="lvl-open">OPEN</span>' : lvlChip(cur)) + '</span>' +
      '<select class="inp mg-lvsel" data-lvlsec="' + r.id + '" aria-label="Level for ' + esc(r.name) + '">' +
        ['open', 'personal', 'private'].map(function(l){ return '<option value="' + l + '"' + (cur === l ? ' selected' : '') + '>' + l.charAt(0).toUpperCase() + l.slice(1) + '</option>'; }).join('') +
      '</select></div>';
  }).join('');
  return '<div class="card mg-card"><h3>Levels</h3>' +
    '<p class="sub">A level gates what the display role (top bar) shows: Open role sees Open sections only, Personal adds Personal, Private shows everything. Sections above the role are hidden entirely — removed from the page, not blurred. Assignments live on this device in the app\u2019s local settings (localStorage overlay <b>' + LVL_KEY + '</b>), the same pattern as the organization registry. Personal sections carry a deep amber/bronze ground, Private a maroon ground, and both show a level chip on the band header.</p>' +
    '<div class="mg-lvhead"><span>Section / field</span><span>Kind</span><span>Level</span><span>Reassign</span></div>' + rows + '</div>';
}
/* Bulk proximity log (V3.68.0): pick a group, one date, one venue —
   everyone is checked by default; uncheck absences; one save files a
   Proximity event per checked person through the normal outbox.
   A Proximity event carries date + venue only and never touches
   Last Contact. */
var MGPROX = { group:'', off:{}, venue:'', date:'', appliedFor:'', dirtyFor:'' };
/* V4.3.0 (JD 2026-11-04): the logger preloads the people JD will
   actually cross paths with on the chosen date. Lewis School days
   follow his PT/OT split — Monday both programs (the full set),
   Tuesday and Friday OT, Wednesday and Thursday PT; the anatomy
   instructor and the two office staff are there every workday,
   the Dean on Mondays. Drill days load the S1 pool instead.
   Preload only sets the starting state for a date; once JD
   touches the checkboxes or the group for that date, his state
   wins (dirtyFor). */
var PX_PT = ['Samantha Marocco', 'Heather Shattuck', 'Christopher Towler', 'David DiSalvo', 'Jaime Bicknell', 'Kwadwo Appiah-Kubi', 'Kara Ferguson', 'Dale Fournier'];
var PX_OT = ['Alisha Ohl', 'Ashleigh Graveline', 'Karen Hoover', 'Beth Randall', 'Brittany DiSalvo'];
var PX_BOTH = ['Robin DiPasquale', 'Richard Tacchino', 'Tammy Monroe'];
var PX_MON = ['Lennart Johns'];
var PXCAL = null, PXCAL_TRIED = false;
function pxCalEnsure(){
  if(PXCAL_TRIED) return; PXCAL_TRIED = true;
  fetch('data/calendar.json?v=' + APP_VERSION).then(function(r){ return r.ok ? r.json() : null; }).then(function(j){
    PXCAL = j;
    var ds = MGPROX.date || todayStr();
    if(MGPROX.appliedFor === ds && pxIsDrill(ds)){ MGPROX.appliedFor = ''; MGPROX.dirtyFor = ''; if($('#pv-proxlogger')) render(); }
  }).catch(function(){ PXCAL = null; });
}
function pxDrillSet(){
  var set = {};
  if(!PXCAL || !PXCAL.entries) return set;
  PXCAL.entries.forEach(function(en){
    var t = String(en.title || '');
    if(!(/UTA|Drill/i.test(t) || en.cal === 'Military')) return;
    var ds = en.dates && en.dates.length ? en.dates : (en.date ? [en.date] : []);
    ds.forEach(function(d){ set[d] = 1; });
  });
  /* a drill block runs through its weekend: Thu/Fri starts cover
     Fri–Sun, a Saturday start covers Sunday */
  Object.keys(set).forEach(function(d){
    var p = d.split('-'), dt = new Date(+p[0], +p[1] - 1, +p[2]), wd = dt.getDay(), add = wd === 4 ? 3 : (wd === 5 ? 2 : (wd === 6 ? 1 : 0));
    for(var i = 1; i < add; i++){ var n = new Date(dt.getTime() + i * 864e5); set[n.getFullYear() + '-' + String(n.getMonth() + 1).padStart(2, '0') + '-' + String(n.getDate()).padStart(2, '0')] = 1; }
  });
  return set;
}
function pxIsDrill(ds){ return !!pxDrillSet()[ds]; }
function pxPreload(ds){
  if(MGPROX.appliedFor === ds || MGPROX.dirtyFor === ds) return;
  MGPROX.appliedFor = ds;
  var groups = allGroups();
  if(pxIsDrill(ds) && groups['S1']){
    MGPROX.group = 'S1'; MGPROX.off = {}; MGPROX.venue = 'UTA Drill'; return;
  }
  var p = ds.split('-'), wd = new Date(+p[0], +p[1] - 1, +p[2]).getDay();
  if(!groups['Lewis School'] || wd === 0 || wd === 6) return;
  var members = groups['Lewis School'];
  var want = null;
  if(wd === 1) want = null;                                        /* Monday: everyone */
  else if(wd === 2 || wd === 5) want = PX_OT.concat(PX_BOTH);      /* OT days */
  else want = PX_PT.concat(PX_BOTH);                               /* PT days */
  MGPROX.group = 'Lewis School';
  if(!MGPROX.venue) MGPROX.venue = 'Lewis School, Clarkson Hall';
  MGPROX.off = {};
  if(want){
    var keep = {};
    members.forEach(function(di){ if(want.indexOf(dispName(D.directory[di])) >= 0) keep[di] = 1; });
    members.forEach(function(di){ if(!keep[di]) MGPROX.off[di] = 1; });
  }
}
function pxCheckedCount(){
  var members = allGroups()[MGPROX.group] || [];
  return members.filter(function(di){ return !MGPROX.off[di]; }).length;
}
function mgProxHTML(){
  /* V4.1: anchor target for the Calendar header's Log proximity link */
  if(!MGPROX.date) MGPROX.date = todayStr();
  pxCalEnsure();
  pxPreload(MGPROX.date);
  var groups = Object.keys(allGroups()).sort();
  if(!MGPROX.group || !allGroups()[MGPROX.group]) MGPROX.group = allGroups()['Lewis School'] ? 'Lewis School' : (groups[0] || '');
  if(!MGPROX.venue) MGPROX.venue = MGPROX.group === 'Lewis School' ? 'Lewis School, Clarkson Hall' : '';
  var members = allGroups()[MGPROX.group] || [];
  var rows = members.map(function(di){
    var e = D.directory[di], lp = lastProx(e);
    return '<label class="px-row"><input type="checkbox" data-pxmem="' + di + '"' + (MGPROX.off[di] ? '' : ' checked') + '>' + avatar(e, 'sm') +
      '<span class="px-name"><b>' + esc(dispName(e)) + '</b>' + (lp ? '<small>Last proximity ' + esc(ykLabelOf(lp.date)) + '</small>' : '<small>No proximity yet</small>') + '</span></label>';
  }).join('');
  return '<div class="card mg-card mg-prox" id="pv-proxlogger"><div class="mg-prox-h"><h3>Proximity — bulk log</h3>' + kindChip('connection', true) + '</div>' +
    '<p class="sub">Co-presence only — a date and a place. Last Contact never moves.</p>' +
    '<div class="frow px-controls"><label>Group<select class="inp" data-pxgroup>' +
      groups.map(function(g){ return '<option value="' + esc(g) + '"' + (g === MGPROX.group ? ' selected' : '') + '>' + esc(g) + ' (' + (allGroups()[g] || []).length + ')</option>'; }).join('') +
      '</select></label>' +
      '<label>Date<input class="inp" type="date" id="px-date" data-pxdate value="' + esc(MGPROX.date || todayStr()) + '"></label>' +
      '<label class="grow">Place / context<input class="inp" type="text" id="px-venue" value="' + esc(MGPROX.venue) + '" placeholder="Lewis School, Clarkson Hall"></label></div>' +
    '<div class="row px-bar"><button type="button" class="btn ghost sm" data-act="proxall">Check all</button>' +
      '<button type="button" class="btn ghost sm" data-act="proxnone">Uncheck all</button>' +
      '<span class="sub"><b id="px-count">' + pxCheckedCount() + '</b> of ' + members.length + ' will be logged</span><span class="sp"></span>' +
      '<button type="button" class="btn primary" data-act="proxbulk">Log proximity for checked</button></div>' +
    '<div class="px-list">' + (rows || '<p class="sub">No groups yet.</p>') + '</div></div>';
}

/* ---------- WS-F: Sandbox Stats Explorer ----------
   Read-only; computed client-side from the baked data the app
   already loads. Field definitions reuse the same helpers as
   Home / Audit / People (footprintOf, phIndex + phHasPhoto,
   ptLocVal, personGroups, famLinks, msgFor, knownSinceYear,
   firstContactOf, lcOnline, scoreFor), so the counts match. */
function sePhotoHas(e){
  var idx = phIndex(); if(!idx) return false;
  var p = idx[dispName(e)]; return !!(p && phHasPhoto(p));
}
var SE_FIELDS = [
  { k:'synopsis', l:'Synopsis', has:function(e){ return !!String(gv(e, 'synopsis') || '').trim(); } },
  { k:'footprint', l:'Public Footprint', has:function(e){ return footprintOf(e).blocks > 0; } },
  { k:'photo', l:'Photo', has:function(e){ return sePhotoHas(e); } },
  { k:'location', l:'Location', has:function(e){ return !!ptLocVal(e); } },
  { k:'church', l:'Church', has:function(e){ return tagList(gv(e, 'churches')).length > 0; } },
  { k:'companies', l:'Companies', has:function(e){ return tagList(gv(e, 'companies')).length > 0; } },
  { k:'universities', l:'Universities', has:function(e){ return tagList(gv(e, 'universities')).length > 0; } },
  { k:'skills', l:'Skills', has:function(e){ return tagList(gv(e, 'specialty')).length > 0; } },
  { k:'groups', l:'Groups', has:function(e){ return personGroups(e).length > 0; } },
  { k:'family', l:'Family', has:function(e){ return famLinks(e).length > 0; } },
  { k:'contact', l:'Phone', has:function(e){ return !!(String(gv(e, 'phone') || '').trim() || String(gv(e, 'email') || '').trim()); } },   /* V3.75.0 (bug hunt 4 UI half): emails are deliberately scrubbed from the published data (standing privacy decision, 2026-10-06), so this counts phone only — the label now says so */
  { k:'events', l:'Events', has:function(e){ return (e.events || []).length > 0; } },
  { k:'corr', l:'Correspondence', has:function(e){ return !!msgFor(e); } },
  { k:'years', l:'Years Known', has:function(e){ return !!knownSinceYear(e); } },
  { k:'firstc', l:'First Contact', has:function(e){ return !!firstContactOf(e); } },
  { k:'lastc', l:'Last Contact', has:function(e){ return !!String(gv(e, 'last_contact') || '').trim(); } },
  { k:'online', l:'Last Online', has:function(e){ return lcOnline(e); } },
  { k:'rel', l:'Relationship', has:function(e){ return !!String(gv(e, 'relationship') || '').trim(); } }
];
function seFieldDef(k){ for(var i = 0; i < SE_FIELDS.length; i++) if(SE_FIELDS[i].k === k) return SE_FIELDS[i]; return null; }
function seFilledCount(di){ var e = D.directory[di], n = 0; SE_FIELDS.forEach(function(f){ if(f.has(e)) n++; }); return n; }
function seDistGroups(){
  var P = people(), groups = [];
  var bands = [[0, 24], [25, 49], [50, 74], [75, 89], [90, 100]].map(function(b){
    return { label:'Completeness ' + b[0] + '\u2013' + b[1], dis:P.filter(function(di){ var s = scoreFor(di).score; return s >= b[0] && s <= b[1]; }) };
  });
  groups.push({ title:'Completeness bands', rows:bands });
  var rel = {};
  P.forEach(function(di){ var r = cap(gv(D.directory[di], 'relationship')) || 'Untyped'; (rel[r] = rel[r] || []).push(di); });
  groups.push({ title:'Relationship mix', rows:Object.keys(rel).sort(function(a, b){ return rel[b].length - rel[a].length; }).map(function(r){ return { label:r, dis:rel[r] }; }) });
  var towns = {};
  P.forEach(function(di){ var t = ptLocVal(D.directory[di]); if(!t) return; var town = t.split(',')[0].trim(); if(town) (towns[town] = towns[town] || []).push(di); });
  groups.push({ title:'Top locations / towns', rows:Object.keys(towns).sort(function(a, b){ return towns[b].length - towns[a].length; }).slice(0, 15).map(function(t){ return { label:t, dis:towns[t] }; }) });
  var ag = allGroups();
  groups.push({ title:'Group sizes', rows:Object.keys(ag).filter(function(g){ return ag[g].length; }).sort(function(a, b){ return ag[b].length - ag[a].length; }).slice(0, 15).map(function(g){ return { label:g, dis:ag[g].slice() }; }) });
  var dec = {};
  P.forEach(function(di){ var y = knownSinceYear(D.directory[di]); if(!y) return; var dl = Math.floor(y / 10) * 10 + 's'; (dec[dl] = dec[dl] || []).push(di); });
  groups.push({ title:'Years known by decade', rows:Object.keys(dec).sort().map(function(dl){ return { label:'Known since the ' + dl, dis:dec[dl] }; }) });
  var t0 = new Date(); t0.setHours(0, 0, 0, 0);
  var rec = { a:[], b:[], c:[], d:[], n:[] };
  P.forEach(function(di){
    var f = hmLastKey(D.directory[di]);   /* V3.75.0 (bug hunt 5): shared recency — "Never" only when no stamp AND no dated contact events */
    if(f == null){ rec.n.push(di); return; }
    var days = Math.floor((t0.getTime() - f) / 864e5);
    if(days <= 7) rec.a.push(di); else if(days <= 30) rec.b.push(di); else if(days <= 90) rec.c.push(di); else rec.d.push(di);
  });
  groups.push({ title:'Last-contact recency', rows:[{ label:'Within 7 days', dis:rec.a }, { label:'8\u201330 days', dis:rec.b }, { label:'31\u201390 days', dis:rec.c }, { label:'Over 90 days', dis:rec.d }, { label:'Never / not recorded', dis:rec.n }] });
  return groups;
}
function sbStats(){
  phLoad(); msgLoad();
  if(SB.se.view === 'list' && SB.se.list) return seListHTML();
  var P = people(), total = P.length || 1;
  var frows = SE_FIELDS.map(function(f){
    var n = P.filter(function(di){ return f.has(D.directory[di]); }).length, pct = Math.round(n / total * 100);
    return '<div class="se-frow"><span class="se-fl">' + f.l + '</span>' +
      '<span class="se-bar"><button type="button" class="se-seg has" data-act="sefield" data-f="' + f.k + '" data-seg="has" style="flex:' + n + '" title="Filled — the ' + n + ' people who have it">' + (n ? n : '') + '</button>' +
      '<button type="button" class="se-seg miss" data-act="sefield" data-f="' + f.k + '" data-seg="miss" style="flex:' + (total - n) + '" title="Blank — the ' + (total - n) + ' people missing it">' + ((total - n) ? (total - n) : '') + '</button></span>' +
      '<span class="se-fn">' + pct + '%</span></div>';
  }).join('');
  var dhtml = seDistGroups().map(function(g, gi){
    var max = Math.max.apply(null, g.rows.map(function(r){ return r.dis.length; }).concat([1]));
    return '<div class="card se-card"><h3>' + g.title + '</h3>' + g.rows.map(function(r, ri){
      return '<button type="button" class="se-drow" data-act="sedist" data-g="' + gi + '" data-i="' + ri + '"><span class="se-dl">' + esc(r.label) + '</span><span class="se-dbar"><span style="width:' + Math.round(r.dis.length / max * 100) + '%"></span></span><span class="se-dn">' + r.dis.length + '</span></button>';
    }).join('') + '</div>';
  }).join('');
  var board = P.slice().sort(function(a, b){ return seFilledCount(b) - seFilledCount(a) || dispName(D.directory[a]).localeCompare(dispName(D.directory[b])); }).slice(0, 25);
  SB.se.shown = board;
  var bhtml = board.map(function(di, i){
    var e = D.directory[di], n = seFilledCount(di);
    return '<button type="button" class="se-brow" data-act="seperson" data-di="' + di + '"><span class="se-rank">' + (i + 1) + '</span>' + avatar(e, 'sm') + '<span class="se-bname">' + esc(dispName(e)) + '</span><span class="se-dbar"><span style="width:' + Math.round(n / SE_FIELDS.length * 100) + '%"></span></span><span class="se-dn">' + n + ' / ' + SE_FIELDS.length + '</span></button>';
  }).join('');
  return sbShell('<div class="se-head"><h2 class="sb-h">Stats Explorer</h2><p class="sub">Read-only, computed from the same baked data as Home and Audit — the field definitions match theirs. Every segment, bar, and row opens its people list; Back walks back out the way you came in.</p></div>' +
    '<div class="se-grid"><div class="card se-card"><h3>Field completeness</h3>' + frows + '</div>' +
    '<div class="se-col"><div class="card se-card"><h3>Most fields filled — leaderboard</h3>' + bhtml + '</div>' + dhtml + '</div></div>');
}
function seListHTML(){
  var L = SB.se.list;
  return sbShell('<div class="card se-card"><div class="se-lhead"><button type="button" class="btn ghost sm" data-act="seback">\u2190 All stats</button>' +
    '<h3>' + esc(L.title) + '</h3><span class="chip">' + L.dis.length + ' people</span></div>' +
    '<div class="se-ltools"><input id="se-q" class="inp" placeholder="Search this list" value="' + esc(SB.se.q) + '" autocomplete="off">' +
    '<span class="se-sorts">Sort ' + [['name', 'Name'], ['fields', 'Fields filled'], ['score', 'Completeness'], ['lastc', 'Last contact']].map(function(o){ return '<button type="button" class="btn ghost sm' + (SB.se.sort === o[0] ? ' on' : '') + '" data-act="sesort" data-s="' + o[0] + '">' + o[1] + '</button>'; }).join('') + '</span></div>' +
    '<div id="selist"></div></div>');
}
function seListDis(){
  var L = SB.se.list; if(!L) return [];
  var q = SB.se.q.trim().toLowerCase();
  var dis = L.dis.filter(function(di){ return D.directory[di] && (!q || dispName(D.directory[di]).toLowerCase().indexOf(q) >= 0); });
  var s = SB.se.sort;
  dis.sort(function(a, b){
    if(s === 'fields') return seFilledCount(b) - seFilledCount(a) || dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
    if(s === 'score') return scoreFor(b).score - scoreFor(a).score || dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
    if(s === 'lastc'){
      var ka = flexKey(gv(D.directory[a], 'last_contact')), kb = flexKey(gv(D.directory[b], 'last_contact'));
      if(ka == null && kb == null) return dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
      if(ka == null) return 1;
      if(kb == null) return -1;
      return kb - ka;
    }
    return dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
  });
  return dis;
}
function sePaintList(){
  var box = $('#selist'); if(!box) return;
  var dis = seListDis(); SB.se.shown = dis;
  box.innerHTML = dis.length ? dis.map(function(di){
    var e = D.directory[di];
    return '<button type="button" class="se-prow" data-act="seperson" data-di="' + di + '">' + avatar(e, 'sm') +
      '<span class="se-pname"><b>' + esc(dispName(e)) + '</b><small>' + esc(infoLine(e)) + '</small></span>' +
      '<span class="se-pmeta">' + seFilledCount(di) + ' / ' + SE_FIELDS.length + ' fields · Completeness ' + scoreFor(di).score + (gv(e, 'last_contact') ? ' · Last contact ' + esc(lcDateLabel(gv(e, 'last_contact'))) : '') + '</span></button>';
  }).join('') : '<p class="sub">No one in this list matches the search.</p>';
}
function seScroller(){ return $('.sb-canvas'); }
function seOpenList(title, dis){
  /* The Sandbox scrolls .sb-canvas, not #view (body[data-view=
     "sandbox"] #view is overflow:hidden), so the app view stack's
     #view scroll save cannot see these positions — the Explorer
     keeps its own, here and in sePersonOpen / sbAfterRender. */
  var sc = seScroller();
  SB.se.statsScroll = sc ? sc.scrollTop : navScroll();
  SB.se.listScroll = 0;
  SB.se.view = 'list'; SB.se.list = { title:title, dis:dis.slice() }; SB.se.q = '';
  viewSandbox($('#view'));
  var cv = seScroller(); if(cv) cv.scrollTop = 0;
}
function sePersonOpen(di){
  var sc = seScroller();
  if(sc && SB.se.view === 'list') SB.se.listScroll = sc.scrollTop;
  var shown = SB.se.shown || [];
  openPerson(di, ctxFrom('Stats Explorer', shown, shown.indexOf(di), 'sandbox'));
}
function seOpenField(k, seg){
  var f = seFieldDef(k); if(!f) return;
  var dis = people().filter(function(di){ var h = f.has(D.directory[di]); return seg === 'has' ? h : !h; });
  seOpenList(f.l + (seg === 'has' ? ' — has it' : ' — missing'), dis);
}
function seOpenDist(gi, ri){
  var g = seDistGroups()[+gi]; if(!g || !g.rows[+ri]) return;
  seOpenList(g.title + ' — ' + g.rows[+ri].label, g.rows[+ri].dis);
}
function seBack(){
  SB.se.view = 'stats'; SB.se.list = null; SB.se.q = '';
  viewSandbox($('#view'));
}

/* ---------- Sandbox Record Studio (V3.71.0, JD 2026-11-02) ----------
   The Sandbox home's hero feature: the stats board's working table.
   Every directory profile as a row — view, sort, filter, quick-edit
   cells in place, multi-select, and bulk quick-change — all through
   the app's existing machinery: the People table's column set and
   cell renderers (PT_ALL / PTCELL / ptCols), its popover editor
   (ptEditOpen, so validation and autocomplete match People exactly),
   the CDE date editor for Last Contact, and queuePatch inside txn
   for every write (one batched outbox save, one undo step, the
   local-wins overlay reflects it immediately). No new save path.
   Bulk delete is deliberately absent — the Danger Zone owns it. */
var SST_NUM = { assoc:1, msgs:1, years:1, lastc:1, firstc:1, prox:1 };   /* first click sorts high-to-low */
var SST_BULK_FIELDS = [
  { k:'tier', l:'Set level' }, { k:'rel', l:'Set relationship' }, { k:'loc', l:'Set location' },
  { k:'orgs', l:'Add organization' }, { k:'skills', l:'Add skill' }, { k:'groups', l:'Add to group' }
];
function sstCols(){
  var cols = ptVisibleCols().slice();
  if(roleClears(lvlOf('stamps'))){
    var prox = { k:'prox', label:'Last proximity', kind:'connection', num:true };
    var ix = -1; cols.forEach(function(c, i){ if(c.k === 'lastc') ix = i; });
    if(ix >= 0) cols.splice(ix + 1, 0, prox); else cols.push(prox);
  }
  /* Editorial Grid (V3.73.0): two switched views, each exactly
     band-width — Identity (name, level, location, organizations,
     completeness; the name cell carries the photo) and Fields
     (every remaining structured field). All = the shared set. */
  var vw = (typeof SB !== 'undefined' && SB.st && SB.st.view) || 'all';
  if(vw === 'identity' || vw === 'fields'){
    var IDK = { name:1, tier:1, loc:1, orgs:1, close:1 };
    var sub = cols.filter(function(c){ return vw === 'identity' ? !!IDK[c.k] : !IDK[c.k]; });
    if(sub.length) cols = sub;
  }
  return cols;
}
function sstSortVal(di, k){
  var e = D.directory[di];
  switch(k){
    case 'name': return dispName(e).toLowerCase();
    case 'tier': var t = tierOf(e); return t ? TIER_ORDER.indexOf(t) : 99;
    case 'loc': return ptLocVal(e) ? ptLocVal(e).toLowerCase() : null;
    case 'orgs': var o = orgsOf(e); return o.length ? o.join(', ').toLowerCase() : null;
    case 'assoc': return knownAssociates(e).length;
    case 'msgs': var mf = msgFor(e); return mf ? mf.n : -1;
    case 'skills': var s = tagList(gv(e, 'specialty')); return s.length ? s.join(', ').toLowerCase() : null;
    case 'rel': var r = [cap(gv(e, 'relationship')), effHandle(e) ? '@' + effHandle(e) : ''].filter(Boolean).join(' '); return r ? r.toLowerCase() : null;
    case 'close': return gv(e, 'closeness') || null;
    case 'handle': return effHandle(e) ? effHandle(e).toLowerCase() : null;
    case 'groups': var g = personGroups(e); return g.length ? g.join(', ').toLowerCase() : null;
    case 'years': return knownSinceYear(e) || null;
    case 'phone': return gv(e, 'phone') || null;
    case 'email': return gv(e, 'email') || null;
    case 'lastc': return flexKey(gv(e, 'last_contact'));
    case 'firstc': return flexKey(firstContactOf(e));
    case 'prox': var lp = lastProx(e); return lp ? flexKey(lp.date) : null;
  }
  return null;
}
function sstFiltered(){
  var st = SB.st, pool = people();
  var dis = st.q.trim() ? searchPeople(st.q, 9999, pool) : pool.slice();
  dis = dis.filter(function(di){
    var e = D.directory[di];
    if(st.tier !== 'all'){ var t = tierOf(e); if(st.tier === 'none' ? !!t : t !== st.tier) return false; }
    if(st.group && personGroups(e).indexOf(st.group) < 0) return false;
    return true;
  });
  var k = st.sortK, d = st.sortD;
  dis.sort(function(a, b){
    var va = sstSortVal(a, k), vb = sstSortVal(b, k);
    if(va == null && vb == null) return dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
    if(va == null) return 1;   /* blanks last in both directions */
    if(vb == null) return -1;
    var c = (typeof va === 'number' && typeof vb === 'number') ? va - vb : String(va).localeCompare(String(vb));
    return c ? c * d : dispName(D.directory[a]).localeCompare(dispName(D.directory[b]));
  });
  return dis;
}
function sstSelDis(){
  /* keyed by directory index, not pkey: two live rows can share a
     pkey (the sf:jdmeyers_ shell pair) and each is its own record here */
  return Object.keys(SB.st.sel).map(function(k){ return +k; }).filter(function(di){ return D.directory[di] && liveEntry(D.directory[di]); });
}
function sstTierChips(){
  var st = SB.st;
  return [['all', 'Any level'], ['vetted', 'Vetted'], ['associate', 'Associate'], ['open', 'Open'], ['none', 'No level']].map(function(o){
    return '<button type="button" class="fc' + (st.tier === o[0] ? ' on' : '') + '" data-act="ssttier" data-v="' + o[0] + '">' + o[1] + '</button>';
  }).join('');
}
function sstPaintTiers(){ var t = $('#sst-tiers'); if(t) t.innerHTML = sstTierChips(); }
function sstShell(){
  phLoad(); msgLoad();
  var st = SB.st, groups = Object.keys(allGroups()).sort();
  return '<section class="sst" id="sst" aria-label="Record studio">' +
    '<div class="sst-top"><h3 class="mdl-ph">Record studio</h3><span class="sst-count" id="sst-count"></span><span class="sp"></span>' +
    '<span class="seg sst-viewseg" role="group" aria-label="Studio view">' +
    [['all', 'All columns'], ['identity', 'Identity'], ['fields', 'Fields']].map(function(o){ return '<button type="button" data-act="sstview" data-v="' + o[0] + '"' + ((st.view || 'all') === o[0] ? ' class="on"' : '') + '>' + o[1] + '</button>'; }).join('') + '</span></div>' +
    '<p class="sst-sub">Every profile, one table.</p>' +
    '<div class="sst-tools">' +
      '<label class="field sst-qf"><span>' + ic('search', 15) + '</span><input id="sst-q" type="search" placeholder="Filter by name, school, employer, skill" value="' + esc(st.q) + '" autocomplete="off"></label>' +
      '<span class="chips" id="sst-tiers">' + sstTierChips() + '</span>' +
      '<select id="sst-group" class="inp sst-gsel" aria-label="Filter by group"><option value="">All groups</option>' +
        groups.map(function(g){ return '<option value="' + esc(g) + '"' + (st.group === g ? ' selected' : '') + '>' + esc(g) + '</option>'; }).join('') + '</select>' +
      '<span class="sst-tools-r"><button type="button" class="btn ghost sm" data-act="sstcols">' + ic('settings', 13) + 'Columns</button>' +
      '<button type="button" class="btn ghost sm" data-act="sstclear">Clear</button></span>' +
    '</div>' +
    '<div id="sst-bulk"></div>' +
    '<div id="sst-main"></div>' +
  '</section>';
}
function sstProxCell(e){
  var lp = lastProx(e); if(!lp) return '';
  var s = lcDateLabel(lp.date) + (lp.venue ? ' · ' + lp.venue : '');
  return '<span class="clip" title="' + esc(s) + '">' + esc(s) + '</span>';
}
function sstRowHTML(di, i, cols){
  var e = D.directory[di], sel = !!SB.st.sel[di];
  var tds = cols.map(function(c){
    if(c.k === 'prox') return '<td class="c-prox" data-kind="connection">' + sstProxCell(e) + '</td>';
    if(c.k === 'lastc') return '<td class="c-lastc num" data-kind="connection"><span class="sst-lcc">' + PTCELL.lastc(e) + '</span><button type="button" class="sst-lcbtn" data-act="sstedlc" data-di="' + di + '" title="Edit last contact" aria-label="Edit last contact for ' + esc(dispName(e)) + '">' + ic('edit', 11) + '</button></td>';
    var ed = PT_ED[c.k];
    return '<td class="c-' + c.k + (c.num ? ' num' : '') + '" data-kind="' + (c.kind || 'about') + '"' + (ed ? ' data-ed="' + ed + '" data-di="' + di + '" tabindex="0" title="Shift-click to edit"' : '') + '>' + PTCELL[c.k](e, di) + '</td>';
  }).join('');
  return '<tr class="ptrow sst-row' + (sel ? ' sel' : '') + '" data-act="sstopen" data-di="' + di + '" data-i="' + i + '"><td class="sst-ck" data-act="sstckcell"><input type="checkbox" data-sstck="' + di + '"' + (sel ? ' checked' : '') + ' aria-label="Select ' + esc(dispName(e)) + '"></td>' + tds + '</tr>';
}
function sstPaint(){
  var main = $('#sst-main'); if(!main) return;
  sstPaintBulk();
  var st = SB.st, cols = sstCols(), dis = sstFiltered();
  SB.se.shown = dis;
  var cnt = $('#sst-count');
  if(cnt) cnt.textContent = (dis.length === people().length ? dis.length + ' people' : dis.length + ' of ' + people().length + ' people') + (sstSelDis().length ? ' · ' + sstSelDis().length + ' selected' : '');
  if(!dis.length){
    main.innerHTML = '<div class="empty"><h3>No one matches.</h3><p>Loosen a filter or clear the search.</p></div>';
    return;
  }
  var head = '<thead><tr><th class="sst-ckh"><input type="checkbox" data-sstckall aria-label="Select all rows in the current view"></th>' + cols.map(function(c){
    var on = st.sortK === c.k;
    return '<th class="' + (c.num ? 'num' : '') + (on ? ' on' : '') + '" data-kind="' + (c.kind || 'about') + '" data-act="sstsort" data-k="' + c.k + '" tabindex="0" aria-sort="' + (on ? (st.sortD < 0 ? 'descending' : 'ascending') : 'none') + '" title="Sort by ' + esc(c.label.toLowerCase()) + '">' + esc(c.label) + '<span class="sarr" aria-hidden="true">' + (on ? (st.sortD < 0 ? '▾' : '▴') : '') + '</span></th>';
  }).join('') + '</tr></thead>';
  var cg = '<colgroup><col style="width:34px">' + cols.map(function(c){ return '<col style="width:' + (c.k === 'prox' ? 12 : (PT_W[c.k] || 10)) + '%">'; }).join('') + '</colgroup>';
  main.innerHTML = '<div class="ptwrap sst-wrap"><table class="ptable sst-table">' + cg + head + '<tbody>' +
    dis.map(function(di, i){ return sstRowHTML(di, i, cols); }).join('') + '</tbody></table></div>';
  sstPaintSelState();
}
function sstPaintSelState(){
  var dis = sstFiltered(), sel = sstSelDis(), inView = dis.filter(function(di){ return SB.st.sel[di]; }).length;
  var ck = document.querySelector('[data-sstckall]');
  if(ck){ ck.checked = dis.length > 0 && inView === dis.length; ck.indeterminate = inView > 0 && inView < dis.length; }
  var cnt = $('#sst-count');
  if(cnt) cnt.textContent = (dis.length === people().length ? dis.length + ' people' : dis.length + ' of ' + people().length + ' people') + (sel.length ? ' · ' + sel.length + ' selected' : '');
  var bn = $('#sst-bulk-n'); if(bn) bn.textContent = sel.length + ' selected';
  sstPaintBulkMode();
}
/* The bulk bar appears/disappears with the selection; while it is up,
   only its count line is touched from row toggles, so a half-typed
   quick-change value is never wiped by a repaint. */
function sstPaintBulkMode(){
  var bar = $('#sst-bulk'), n = sstSelDis().length;
  if(!bar) return;
  var has = !!bar.firstChild;
  if((n > 0) !== has || SB.st.result) sstPaintBulk();
}
function sstBulkValHTML(){
  var st = SB.st, f = st.bulkF;
  if(f === 'tier') return '<select id="sst-bv-sel" class="inp" aria-label="Level to set">' + TIER_ORDER.map(function(t){ return '<option value="' + t + '"' + (st.bulkV === t ? ' selected' : '') + '>' + TIERS[t].n + '</option>'; }).join('') + '<option value=""' + (st.bulkV === '' ? ' selected' : '') + '>No level yet</option></select>';
  if(f === 'rel') return '<select id="sst-bv-sel" class="inp" aria-label="Relationship to set"><option value=""' + (st.bulkV === '' ? ' selected' : '') + '>Not set</option>' + REL_OPTS.map(function(r){ return '<option value="' + esc(r) + '"' + (st.bulkV === r ? ' selected' : '') + '>' + esc(cap(r)) + '</option>'; }).join('') + '</select>';
  if(f === 'loc') return '<input id="sst-bv-text" class="inp" placeholder="Town, ST" value="' + esc(st.bulkV) + '" autocomplete="off">';
  if(f === 'orgs') return '<select id="sst-bcat" class="inp" aria-label="Organization category">' + ORG_CATS.map(function(c){ return '<option value="' + c.k + '"' + (st.bulkCat === c.k ? ' selected' : '') + '>' + c.label + '</option>'; }).join('') + '</select><input id="sst-bv-text" class="inp" placeholder="Organization to add" value="' + esc(st.bulkV) + '" autocomplete="off">';
  if(f === 'skills') return '<input id="sst-bv-text" class="inp" placeholder="Skill to add" value="' + esc(st.bulkV) + '" autocomplete="off">';
  if(f === 'groups'){
    var all = Object.keys(allGroups()).sort();
    return '<select id="sst-bv-sel" class="inp" aria-label="Group to add">' + all.map(function(g){ return '<option value="' + esc(g) + '"' + (st.bulkV === g ? ' selected' : '') + '>' + esc(g) + '</option>'; }).join('') + '</select><input id="sst-bv-newgrp" class="inp" placeholder="or a new group name" value="' + esc(st.bulkGrp) + '" autocomplete="off">';
  }
  return '';
}
function sstPaintBulk(){
  var bar = $('#sst-bulk'); if(!bar) return;
  var st = SB.st, n = sstSelDis().length;
  if(!n && !st.result){ bar.innerHTML = ''; return; }
  var h = '<div class="sst-bulkbar">';
  if(st.result) h += '<div class="sst-result">' + esc(st.result) + '</div>';
  if(n){
    if(st.confirm){
      var plan = sstBulkPlan();
      h += '<div class="sst-confirm"><span class="sst-cq">' + esc(plan.summary) + '</span><span class="sst-cbtns">' +
        '<button type="button" class="btn primary sm" data-act="sstbulkgo">Apply to ' + plan.changes.length + '</button>' +
        '<button type="button" class="btn ghost sm" data-act="sstbulkno">Cancel</button></span></div>';
    } else {
      h += '<div class="sst-bulkrow"><b id="sst-bulk-n">' + n + ' selected</b>' +
        '<button type="button" class="btn ghost sm" data-act="sstselall">Select all in view</button>' +
        '<button type="button" class="btn ghost sm" data-act="sstselnone">Select none</button>' +
        '<span class="sst-bulkctl"><label for="sst-bf">Quick change</label>' +
        '<select id="sst-bf" class="inp">' + SST_BULK_FIELDS.map(function(bf){ return '<option value="' + bf.k + '"' + (st.bulkF === bf.k ? ' selected' : '') + '>' + bf.l + '</option>'; }).join('') + '</select>' +
        sstBulkValHTML() +
        '<button type="button" class="btn sm" data-act="sstbulk">Review…</button></span></div>';
    }
  }
  bar.innerHTML = h + '</div>';
}
function sstBulkPlan(){
  var st = SB.st, sel = sstSelDis(), f = st.bulkF, changes = [];
  function selVal(){ var el = $('#sst-bv-sel'); return el ? el.value : st.bulkV; }
  function textVal(){ var el = $('#sst-bv-text'); return el ? el.value.trim() : String(st.bulkV || '').trim(); }
  function plan(summary, doneLabel, extra){ return Object.assign({ changes:changes, summary:summary, doneLabel:doneLabel, f:f }, extra || {}); }
  if(f === 'tier'){
    var v = selVal(), lbl = v ? TIERS[v].n : 'No level yet';
    sel.forEach(function(di){ if(tierOf(D.directory[di]) !== v){ var p = {}; p.tier = v; changes.push({ di:di, patch:p }); } });
    return plan('Set level to ' + lbl + ' — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'level set to ' + lbl);
  }
  if(f === 'rel'){
    var rv = selVal(), rlbl = rv ? cap(rv) : 'Not set';
    sel.forEach(function(di){ if(String(gv(D.directory[di], 'relationship') || '') !== rv){ var p = {}; p.relationship = rv; changes.push({ di:di, patch:p }); } });
    return plan('Set relationship to ' + rlbl + ' — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'relationship set to ' + rlbl);
  }
  if(f === 'loc'){
    var lv = ptNormLoc(textVal());
    if(!lv) return plan('Type a location first — nothing to apply.', '');
    sel.forEach(function(di){ if(String(gv(D.directory[di], 'location_on_file') || '') !== lv){ var p = {}; p.location_on_file = lv; changes.push({ di:di, patch:p }); } });
    return plan('Set location to ' + lv + ' — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'location set to ' + lv);
  }
  if(f === 'orgs'){
    var raw = textVal();
    if(!raw) return plan('Type an organization first — nothing to apply.', '');
    var cat = st.bulkCat, val = orgPrefixComplete(regApply(raw), cat);
    var catLbl = (ORG_CATS.filter(function(c){ return c.k === cat; })[0] || {}).label || cat;
    sel.forEach(function(di){
      var tags = splitTags(gv(D.directory[di], cat), ', ');
      if(tags.map(function(x){ return x.toLowerCase(); }).indexOf(val.toLowerCase()) < 0){ var p = {}; p[cat] = tags.concat([val]).join(', '); changes.push({ di:di, patch:p }); }
    });
    return plan('Add ' + val + ' (' + catLbl + ') — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'added ' + val + ' (' + catLbl + ')', { regVal:val });
  }
  if(f === 'skills'){
    var sv = textVal();
    if(!sv) return plan('Type a skill first — nothing to apply.', '');
    sel.forEach(function(di){
      var tags = splitTags(gv(D.directory[di], 'specialty'), ', ');
      if(tags.map(function(x){ return x.toLowerCase(); }).indexOf(sv.toLowerCase()) < 0){ var p = {}; p.specialty = tags.concat([sv]).join(', '); changes.push({ di:di, patch:p }); }
    });
    return plan('Add skill ' + sv + ' — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'added skill ' + sv);
  }
  if(f === 'groups'){
    var ng = $('#sst-bv-newgrp') ? $('#sst-bv-newgrp').value.trim() : String(st.bulkGrp || '').trim();
    var g = ng ? regApply(ng) : selVal();
    if(!g) return plan('Pick or name a group first — nothing to apply.', '');
    sel.forEach(function(di){
      var gl = personGroups(D.directory[di]);
      if(gl.indexOf(g) < 0){ var p = {}; p.groups = gl.concat([g]).join(', '); changes.push({ di:di, patch:p }); }
    });
    return plan('Add to group ' + g + ' — ' + changes.length + ' of ' + sel.length + ' selected records will change.', 'added to group ' + g, { newGroup:ng ? g : '' });
  }
  return plan('', '');
}
function sstBulkApply(){
  var plan = sstBulkPlan();
  if(!plan.changes.length){ SB.st.confirm = false; sstPaintBulk(); return; }
  if(plan.f === 'orgs' && plan.regVal && !ORGREG.canon[regKey(plan.regVal)]) regRegisterCanon(plan.regVal, SB.st.bulkCat);
  if(plan.f === 'groups' && plan.newGroup){
    if(!allGroups()[plan.newGroup]){ GRP_EXTRA.push(plan.newGroup); store('ncc_groups_extra', JSON.stringify(GRP_EXTRA)); }
    if(!ORGREG.canon[regKey(plan.newGroup)]) regRegisterCanon(plan.newGroup, 'groups');
  }
  txn('Studio bulk change', function(){ plan.changes.forEach(function(c){ queuePatch(c.di, c.patch); }); });
  SB.st.result = 'Patched ' + plan.changes.length + ' record' + (plan.changes.length === 1 ? '' : 's') + ' — ' + plan.doneLabel + '.';
  sbLogAdd({ type:'edit', title:'Record studio bulk: ' + plan.doneLabel, detail:plan.changes.length + ' records' });
  SB.st.confirm = false; SB.st.sel = {};
  sstPaint();
  toast(SB.st.result);
}
function sstSelectView(on){
  var dis = sstFiltered();
  dis.forEach(function(di){ if(on) SB.st.sel[di] = true; else delete SB.st.sel[di]; });
  SB.st.confirm = false;
  sstPaint();
}
